// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance (and on the task runner, if task runners are used).
// Same rules as verifyWebhook()/acceptWebhook() in packages/automation/src/webhook.ts:
// HMAC-SHA256 over `${timestamp}.${rawBody}`, constant-time compare, +/-300 s window (inclusive), replay rejection, fail closed.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const REPLAY_TTL_SECONDS = MAX_SKEW_SECONDS * 2;

const reject = (reason) => [{ json: { ok: false, reason } }];
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const secret = String($env.DEPLOY_WEBHOOK_SECRET || '');

if (!secret) return reject('missing_secret');
const signature = headers['x-ablepoint-signature'];
if (!signature) return reject('missing_signature');

const timestamp = headers['x-ablepoint-timestamp'];
const tsText = String(timestamp === undefined || timestamp === null ? '' : timestamp);
if (!/^\d{1,12}$/.test(tsText)) return reject('invalid_timestamp');
const ts = Number(tsText);
const maxMs = MAX_SKEW_SECONDS * 1000;
const skewMs = Date.now() - ts * 1000;
if (skewMs > maxMs) return reject('timestamp_too_old');
if (skewMs < -maxMs) return reject('timestamp_in_future');

const sigHex = String(signature).replace(/^sha256=/i, '').toLowerCase();
if (!/^[0-9a-f]{64}$/.test(sigHex)) return reject('bad_signature');

// The signature covers the raw request body, so the Webhook node has "Raw Body" switched on and the body arrives as binary data.
let raw = null;
try {
  if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  raw = null;
}
if (raw === null && item.binary && item.binary.data && typeof item.binary.data.data === 'string') raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
if (raw === null) return reject('raw_body_unavailable');

const expected = crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest();
const provided = Buffer.from(sigHex, 'hex');
if (provided.length !== expected.length || !crypto.timingSafeEqual(provided, expected)) return reject('bad_signature');

// Replay guard. Workflow static data is only saved for production (active) executions, not for test runs in the editor.
const replayKey = crypto.createHash('sha256').update(ts + '.' + sigHex).digest('hex');
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const nowMs = Date.now();
for (const k of Object.keys(store.seen)) if (store.seen[k] <= nowMs) delete store.seen[k];
if (store.seen[replayKey]) return reject('replayed');
store.seen[replayKey] = nowMs + REPLAY_TTL_SECONDS * 1000;

// Optional list of changed paths. Anything not in the sitemap is ignored later.
let paths = [];
try {
  const parsed = JSON.parse(raw);
  if (parsed && Array.isArray(parsed.paths)) paths = parsed.paths.filter((x) => typeof x === 'string' && x.startsWith('/')).slice(0, 10000);
} catch (e) {
  paths = [];
}
return [{ json: { ok: true, paths } }];

// IndexNow must never be told about staging, previews or local builds (apps/web/scripts/indexnow.mjs refuses localhost, staging and example.invalid).
// This guard is stricter: SITE_BASE_URL must be an https origin whose host is exactly PRODUCTION_HOST.
const NON_PRODUCTION = /localhost|staging|example\.invalid|vercel\.app/i;
const refuse = (reason) => [{ json: { allowed: false, reason } }];
const base = String($env.SITE_BASE_URL || '').trim();
const expectedHost = String($env.PRODUCTION_HOST || '').trim().toLowerCase();

let url;
try { url = new URL(base); } catch (e) { return refuse('site_base_url_invalid'); }
if (url.protocol !== 'https:') return refuse('site_base_url_not_https');
if (url.origin !== base) return refuse('site_base_url_must_be_an_origin_without_a_path_or_trailing_slash');
if (!expectedHost) return refuse('production_host_not_configured');
if (url.host.toLowerCase() !== expectedHost) return refuse('site_base_url_is_not_the_production_host');
if (NON_PRODUCTION.test(url.host)) return refuse('non_production_host_pattern');
return [{ json: { allowed: true, host: url.host, origin: url.origin } }];

// Same rules as buildPayload() in apps/web/scripts/indexnow.mjs: URLs on the site host only, de-duplicated, 1 to 10,000 URLs, key of 8 to 128 letters, digits or hyphens.
const KEY_PATTERN = /^[a-zA-Z0-9-]{8,128}$/;
const MAX_URLS = 10000;
const fail = (reason) => [{ json: { ready: false, reason } }];

const guard = $('Production host guard').first().json;
const verified = $('Verify signature').first().json;
const key = String($env.INDEXNOW_KEY || '').trim();
const res = $input.first().json || {};
const xml = typeof res.data === 'string' ? res.data : typeof res.body === 'string' ? res.body : '';
const decode = (s) => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');

if (!KEY_PATTERN.test(key)) return fail('indexnow_key_invalid');
if (xml.indexOf('<urlset') < 0) return fail('sitemap_missing_or_not_a_urlset');

const locs = [...new Set((xml.match(/<loc>[^<]+<\/loc>/g) || []).map((m) => decode(m.replace(/<\/?loc>/g, '').trim())))];
for (const u of locs) {
  let parsed;
  try { parsed = new URL(u); } catch (e) { return fail('sitemap_contains_an_invalid_url'); }
  if (parsed.host !== guard.host) return fail('sitemap_contains_a_url_on_another_host');
}

let urlList = locs;
if (Array.isArray(verified.paths) && verified.paths.length) {
  const wanted = new Set();
  for (const p of verified.paths) {
    try { wanted.add(new URL(p, guard.origin).toString()); } catch (e) { /* ignore a bad path */ }
  }
  urlList = locs.filter((u) => wanted.has(u));
}
if (urlList.length === 0) return fail('no_urls_to_submit');
if (urlList.length > MAX_URLS) return fail('too_many_urls');

return [{ json: { ready: true, count: urlList.length, payload: { host: guard.host, key, keyLocation: new URL('/indexnow-key.txt', guard.origin).toString(), urlList } } }];

// IndexNow answers 200 (received) or 202 (received, key validation pending) on success. 400, 403, 422 and 429 are failures.
const payload = $('Build IndexNow payload').first().json;
const r = $input.first().json || {};
const status = Number(r.statusCode);
const ok = status === 200 || status === 202;
return [{
  json: {
    ok,
    indexNowStatus: Number.isFinite(status) ? status : null,
    submitted: ok ? payload.count : 0,
    httpStatus: ok ? 200 : 502,
    notifySubject: 'IndexNow submission was not accepted',
    notifyText: [
      'The post-deploy IndexNow submission was not accepted.',
      'Status returned: ' + (Number.isFinite(status) ? status : 'none'),
      'URLs in the request: ' + payload.count,
      '400 means a malformed request, 403 an invalid key, 422 URLs that do not belong to the host, 429 too many requests.',
      'Search engines other than Bing-family engines are not affected. Google does not use IndexNow.',
    ].join('\n'),
  },
}];
